// Python `repr()` formatting for byte sequences and text strings.
//
// The byte sequence is modelled as a PLAIN JavaScript Array of integers in
// 0..255. No binary-view type is used anywhere in this bundle.

const CODE_TAB = 0x09;
const CODE_LF = 0x0a;
const CODE_CR = 0x0d;
const CODE_SPACE = 0x20;
const CODE_QUOTE_DOUBLE = 0x22;
const CODE_QUOTE_SINGLE = 0x27;
const CODE_BACKSLASH = 0x5c;
const CODE_TILDE = 0x7e;

/**
 * CPython's quote-selection rule, shared by `bytes.__repr__` and
 * `str.__repr__`:
 *
 *   - default to a single quote;
 *   - if the value contains `'` but no `"`, switch to a double quote so the
 *     apostrophe can be written literally;
 *   - if it contains both, stay on the single quote and backslash-escape the
 *     `'` (the `"` is then written literally).
 *
 * @param {boolean} hasSingle whether the value contains U+0027 / 0x27
 * @param {boolean} hasDouble whether the value contains U+0022 / 0x22
 * @returns {string} the quote character to wrap the literal in
 */
function selectQuote(hasSingle, hasDouble) {
  return hasSingle && !hasDouble ? '"' : "'";
}

/**
 * Two lowercase hex digits, e.g. 0x0a -> "0a", 0xff -> "ff".
 *
 * @param {number} byte an integer in 0..255
 * @returns {string}
 */
function hex2(byte) {
  return byte.toString(16).toLowerCase().padStart(2, '0');
}

/**
 * Four (or more) lowercase hex digits for a `\uXXXX` escape.
 *
 * @param {number} codePoint
 * @param {number} width
 * @returns {string}
 */
function hexN(codePoint, width) {
  return codePoint.toString(16).toLowerCase().padStart(width, '0');
}

/**
 * Render a byte array the way CPython renders a `bytes` object.
 *
 * Escaping rules (measured against CPython 3):
 *   - 0x20..0x7e print as the literal ASCII character, except the active quote
 *     character and the backslash, which are backslash-escaped;
 *   - 0x09 -> `\t`, 0x0a -> `\n`, 0x0d -> `\r`;
 *   - every other byte -> `\xNN` with lowercase hex, always two digits.
 *
 * @param {number[]} bytes plain array of integers 0..255
 * @returns {string} e.g. `b'\x10\xa1'`
 */
export function pyBytesRepr(bytes) {
  const quote = selectQuote(
    bytes.includes(CODE_QUOTE_SINGLE),
    bytes.includes(CODE_QUOTE_DOUBLE),
  );
  const quoteCode = quote === '"' ? CODE_QUOTE_DOUBLE : CODE_QUOTE_SINGLE;

  let body = '';
  for (const byte of bytes) {
    if (byte === quoteCode || byte === CODE_BACKSLASH) {
      body += '\\' + String.fromCharCode(byte);
    } else if (byte >= CODE_SPACE && byte <= CODE_TILDE) {
      body += String.fromCharCode(byte);
    } else if (byte === CODE_TAB) {
      body += '\\t';
    } else if (byte === CODE_LF) {
      body += '\\n';
    } else if (byte === CODE_CR) {
      body += '\\r';
    } else {
      body += '\\x' + hex2(byte);
    }
  }
  return 'b' + quote + body + quote;
}

// `str.isprintable()` is false for the Unicode categories Cc, Cf, Cs, Co, Cn,
// Zl, Zp and Zs -- with the single exception of U+0020, which Python treats as
// printable even though it is Zs.
const NON_PRINTABLE = /[\p{Cc}\p{Cf}\p{Cs}\p{Co}\p{Cn}\p{Zl}\p{Zp}\p{Zs}]/u;

/**
 * @param {string} char a single code point
 * @returns {boolean} CPython's `str.isprintable()` for that code point
 */
function isPrintable(char) {
  if (char === ' ') return true;
  return !NON_PRINTABLE.test(char);
}

/**
 * Render a JavaScript string the way CPython renders a `str` object.
 *
 * Used for the `%r` interpolation in argparse's "invalid int value: %r"
 * message. Note that CPython 3 leaves printable non-ASCII code points as
 * literal characters -- only non-printables are escaped, as `\xNN`, `\uXXXX`
 * or `\UXXXXXXXX` depending on magnitude.
 *
 * @param {string} text
 * @returns {string} e.g. `'abc'`, `"a'b"`, `'\x1c5'`
 */
export function pyStrRepr(text) {
  const quote = selectQuote(text.includes("'"), text.includes('"'));

  let body = '';
  for (const char of text) {
    const codePoint = char.codePointAt(0);
    if (char === quote || char === '\\') {
      body += '\\' + char;
    } else if (char === '\t') {
      body += '\\t';
    } else if (char === '\n') {
      body += '\\n';
    } else if (char === '\r') {
      body += '\\r';
    } else if (isPrintable(char)) {
      body += char;
    } else if (codePoint < 0x100) {
      body += '\\x' + hex2(codePoint);
    } else if (codePoint < 0x10000) {
      body += '\\u' + hexN(codePoint, 4);
    } else {
      body += '\\U' + hexN(codePoint, 8);
    }
  }
  return quote + body + quote;
