  '', ' ', ' ', ' ', ' ', ' ', ' ',
  ' ', ' ', ' ', ' ', ' ', ' ', ' ',
  ' ', ' ', ' ', ' ', '　',
]);

/**
 * @param {string} char a single code point
 * @returns {boolean} whether CPython would fold this away as whitespace
 */
