// Python exception semantics: a chainable exception base class, the interpreter
// call stack that feeds tracebacks, and the traceback renderer itself.
//
// Nothing here knows about `construct`. The construct layer pushes frames onto
// the shared stack as it descends, so the rendered traceback -- and the
// "Error in path (building) -> fieldN" path string that goes with it -- falls
// out of the call structure instead of being spelled out as a literal.

/**
 * One entry of a Python traceback: the source file, the line currently
 * executing in that frame, and the enclosing function name.
 *
 * @param {string} file
 * @param {number} line
 * @param {string} name
 * @returns {{file: string, line: number, name: string}}
 */
export function frame(file, line, name) {
  return { file, line, name };
}

/**
 * Base class for the Python exceptions we reproduce.
 *
 * `qualname` is the dotted name the traceback prints (e.g. `struct.error`,
 * `construct.core.FormatFieldError`). `context` is Python's `__context__`: the
 * exception that was being handled when this one was raised, which is what
 * produces the "During handling of the above exception" section.
 */
export class PythonException extends Error {
  /**
   * @param {string} qualname dotted name as printed by the traceback
   * @param {string} message exception text; may span multiple lines
   * @param {{context?: PythonException|null, frames?: Array<object>}} [options]
   */
  constructor(qualname, message, options = {}) {
    super(message);
    this.name = qualname;
    this.qualname = qualname;
    this.pyMessage = message;
    this.context = options.context ?? null;
    this.frames = options.frames ?? [];
  }
}

/**
 * `struct.error` from the standard library's `struct` module. Raised by the
 * packing primitives when a value will not fit the requested format code.
 */
export class StructError extends PythonException {
  /**
   * @param {string} message
   * @param {{context?: PythonException|null, frames?: Array<object>}} [options]
   */
  constructor(message, options = {}) {
    super('struct.error', message, options);
  }
}

/**
 * Python's `SystemExit`, raised by `sys.exit()` and therefore by argparse.
 *
 * The entry point catches it and translates it into a process exit code, which
 * keeps every exit path in one place and lets stdio drain naturally.
 */
export class SystemExit extends Error {
  /**
   * @param {number} code
   */
  constructor(code) {
    super(`SystemExit: ${code}`);
    this.name = 'SystemExit';
    this.code = code;
  }
}

/**
 * The interpreter call stack.
 *
 * Frames are pushed as the emulated Python functions are entered and popped as
 * they return, so a snapshot taken at the moment an exception is raised is
 * exactly the traceback for it.
 */
export class PythonCallStack {
  constructor() {
    /** @type {Array<{file: string, line: number, name: string}>} */
    this.frames = [];
  }

  /**
   * Run `body` with `entryFrame` pushed onto the stack, popping it again on the
   * way out (including when `body` throws).
   *
   * @template T
   * @param {{file: string, line: number, name: string}} entryFrame
   * @param {() => T} body
   * @returns {T}
   */
  call(entryFrame, body) {
    this.frames.push(entryFrame);
    try {
      return body();
    } finally {
      this.frames.pop();
    }
  }

  /**
   * @returns {Array<{file: string, line: number, name: string}>} a copy of the
   *   current frames, outermost first, as a traceback prints them
   */
  snapshot() {
    return this.frames.slice();
  }
}

/**
 * The single stack shared by the emulated Python modules in this bundle,
 * standing in for the interpreter's own per-thread stack.
 */
export const pythonStack = new PythonCallStack();

const TRACEBACK_HEADER = 'Traceback (most recent call last):';
const CHAIN_SEPARATOR = 'During handling of the above exception, another exception occurred:';

/**
 * @param {{file: string, line: number, name: string}} entry
 * @returns {string}
 */
function renderFrame(entry) {
  return `  File "${entry.file}", line ${entry.line}, in ${entry.name}`;
}

/**
 * Render an exception chain exactly as CPython prints an unhandled exception.
 *
 * The chain is walked to its root first, so the oldest exception is printed at
 * the top and each subsequent one is introduced by the "During handling of the
 * above exception" separator (surrounded by blank lines, as CPython does).
 *
 * @param {PythonException} exception the outermost / most recent exception
 * @returns {string} the traceback text, newline-terminated
 */
export function formatTraceback(exception) {
  /** @type {PythonException[]} */
  const chain = [];
  for (let current = exception; current; current = current.context) {
    chain.unshift(current);
  }

  const lines = [];
  chain.forEach((current, index) => {
    if (index > 0) {
      lines.push('', CHAIN_SEPARATOR, '');
    }
    lines.push(TRACEBACK_HEADER);
    for (const entry of current.frames) {
      lines.push(renderFrame(entry));
    }
    lines.push(`${current.qualname}: ${current.pyMessage}`);
  });

  return lines.join('\n') + '\n';
