 * The trailing line the PyInstaller bootloader prints when the frozen script
 * dies of an unhandled exception. The pid is the live process id, so it differs
 * on every run.
 *
 * @param {number} pid
 * @param {string} scriptStem the frozen script name without extension
 * @returns {string} newline-terminated
 */
export function formatFrozenScriptFailure(pid, scriptStem) {
  return `[PYI-${pid}:ERROR] Failed to execute script '${scriptStem}' due to unhandled exception!\n`;
