// "-> field1" suffix is a consequence of which field was being built rather
// than something written out by hand.

import { PythonException } from '../python/errors.mjs';

/**
 * Base of `construct.core.ConstructError`.
 *
 * construct builds the printed message as `"Error in path <path>\n<detail>"`
 * when a path is known, and just `<detail>` otherwise.
 */
export class ConstructError extends PythonException {
  /**
   * @param {string} qualname dotted class name for the traceback
   * @param {string} detail the error detail, printed after the path line
   * @param {string|null} path the build/parse path, e.g. `(building) -> field1`
   * @param {{context?: PythonException|null, frames?: Array<object>}} [options]
   */
  constructor(qualname, detail, path, options = {}) {
    const message = path ? `Error in path ${path}\n${detail}` : detail;
    super(qualname, message, options);
    this.detail = detail;
    this.path = path;
  }
}

/**
 * `construct.core.FormatFieldError` -- raised by a FormatField when the
 * underlying `struct` packer rejects the value, e.g. because it is outside the
 * range the format code can represent.
 */
