  /**
   * @param {string} detail
   * @param {string|null} path
   * @param {{context?: PythonException|null, frames?: Array<object>}} [options]
   */
  constructor(detail, path, options = {}) {
    super('construct.core.FormatFieldError', detail, path, options);
  }
}

// The construct `Subcon` base class, the byte sink it builds into, and the
// `Renamed` wrapper that implements Python's `"name" / subcon` idiom.
//
// Path tracking lives here. `build()` seeds the path as `(building)`, and every
// Renamed wrapper appends ` -> <name>` before delegating to its inner subcon.
// An error raised deep in the tree therefore already knows its own path.

import { frame, pythonStack } from '../python/errors.mjs';

const CORE = 'construct/core.py';

/**
 * The byte sink `build_stream` writes into.
 *
 * The buffer is a PLAIN JavaScript Array of integers 0..255 -- no binary view
 * type is involved anywhere in this bundle.
 */
export class ByteStream {
  constructor() {
    /** @type {number[]} */
    this.bytes = [];
  }

  /**
   * @param {number[]} bytes integers 0..255 to append
   */
  write(bytes) {
    for (const byte of bytes) {
      this.bytes.push(byte);
    }
  }

  /**
   * @returns {number[]} a copy of everything written so far
   */
  getvalue() {
    return this.bytes.slice();
  }
}

/**
 * Base class for every construct type, mirroring `construct.core.Construct`.
 *
 * Subclasses implement `_build` (and `_parse`, for symmetry with the real
 * library). The public `build`/`parse` entry points own the stream and the
 * initial path.
 */
export class Subcon {
  /**
   * Public build entry point, `Construct.build`.
   *
   * @param {*} obj the value (or object of values) to build from
   * @returns {number[]} the built bytes, as a plain array of integers 0..255
   */
  build(obj) {
    return pythonStack.call(frame(CORE, 452, 'build'), () => {
      const stream = new ByteStream();
      this.buildStream(obj, stream);
      return stream.getvalue();
    });
  }

  /**
   * `Construct.build_stream`: build into a caller-supplied stream.
   *
   * @param {*} obj
   * @param {ByteStream} stream
   * @returns {*} whatever the subcon's `_build` returns
   */
  buildStream(obj, stream) {
    return pythonStack.call(frame(CORE, 464, 'build_stream'), () =>
      // The top-level path construct uses while building.
      this._build(obj, stream, {}, '(building)'),
    );
