import { SystemExit } from '../python/errors.mjs';

/** argparse exits with 2 on a command-line error, 0 after printing help. */
const EXIT_USAGE_ERROR = 2;
const EXIT_OK = 0;

/**
 * `os.path.basename`, for the POSIX and Windows separators.
 *
 * @param {string} path
 * @returns {string}
 */
export function basename(path) {
  const parts = String(path).split(/[/\\]/);
  return parts[parts.length - 1];
}

/**
 * How argparse derives the program name when `prog=` is not given:
 * `os.path.basename(sys.argv[0])`. Under Node the script path is
 * `process.argv[1]`.
 *
 * @param {string[]} argv the full `process.argv`
 * @returns {string}
 */
export function deriveProgName(argv) {
  return basename(argv[1] ?? '');
}

// argparse's `_negative_number_matcher`: a token that looks like a negative
// number is treated as a value rather than an option, provided no registered
// option string itself looks like a negative number.
const NEGATIVE_NUMBER = /^-\d+$|^-\d*\.\d+$/;

/**
 * A single registered optional argument.
 */
class Optional {
  /**
   * @param {string[]} optionStrings e.g. `['--a']` or `['-h', '--help']`
   * @param {{type?: object|null, required?: boolean, nargs?: number,
   *          action?: string, help?: string, metavar?: string}} config
   */
  constructor(optionStrings, config) {
    this.optionStrings = optionStrings;
    this.type = config.type ?? null;
    this.required = config.required ?? false;
    this.action = config.action ?? 'store';
    this.help = config.help ?? null;
    // argparse's default metavar for a `store` optional is the uppercased dest.
    this.dest = optionStrings[optionStrings.length - 1].replace(/^--?/, '');
    this.metavar = config.metavar ?? this.dest.toUpperCase();
  }

  /** @returns {boolean} whether this option consumes a following value */
  get takesValue() {
    return this.action === 'store';
  }

  /**
   * The option as it appears in a usage string / error message: argparse uses
   * the first (longest-prefix) option string.
   *
   * @returns {string}
   */
  get displayName() {
    return this.optionStrings[0];
  }

  /** @returns {string} the `[-h]` / `--a A` fragment for the usage line */
  get usageFragment() {
    return this.takesValue
      ? `${this.displayName} ${this.metavar}`
      : this.displayName;
  }

  /** @returns {string} the left column of the help listing */
  get invocation() {
    return this.optionStrings
      .map((option) => (this.takesValue ? `${option} ${this.metavar}` : option))
      .join(', ');
  }
}

/**
 * The parser itself.
 *
 * Usage mirrors Python:
 *
 *     const parser = new ArgumentParser({ prog });
 *     parser.addArgument('--a', { type: intType, required: true });
 *     const args = parser.parseArgs(argv);
 */
export class ArgumentParser {
  /**
   * @param {{prog: string, stdout?: (text: string) => void,
   *          stderr?: (text: string) => void}} options
   */
  constructor(options) {
    this.prog = options.prog;
    this.writeStdout = options.stdout ?? (() => {});
    this.writeStderr = options.stderr ?? (() => {});
    /** @type {Optional[]} */
    this.optionals = [];
    // argparse registers the help action first, so `[-h]` leads the usage line.
    this.addArgument('-h', '--help', {
      action: 'help',
      help: 'show this help message and exit',
    });
  }

  /**
   * `parser.add_argument(...)`. Option strings come first, the config object
   * last.
   *
   * @param {...(string|object)} args
   * @returns {Optional}
   */
  addArgument(...args) {
    const config =
      typeof args[args.length - 1] === 'object' ? args.pop() : {};
    const optional = new Optional(/** @type {string[]} */ (args), config);
    this.optionals.push(optional);
    return optional;
  }

  /** @returns {string} the `usage: ...` line, without a trailing newline */
  formatUsage() {
    const fragments = this.optionals.map((optional) =>
      optional.required ? optional.usageFragment : `[${optional.usageFragment}]`,
    );
    return `usage: ${this.prog} ${fragments.join(' ')}`;
  }

  /**
   * The full `--help` text.
   *
   * argparse lays the options section out as a two-column table indented by two
   * spaces. When every invocation fits the action column it pads each one to the
   * column width plus a two-space gutter; entries with no help text are emitted
   * without trailing padding.
   *
   * @returns {string} newline-terminated
   */
  formatHelp() {
    const invocations = this.optionals.map((optional) => optional.invocation);
    const column = Math.max(...invocations.map((text) => text.length));

    const lines = [this.formatUsage(), '', 'options:'];
    this.optionals.forEach((optional, index) => {
      const invocation = invocations[index];
      if (optional.help) {
        lines.push(`  ${invocation.padEnd(column)}  ${optional.help}`);
      } else {
        lines.push(`  ${invocation}`);
      }
    });
    return lines.join('\n') + '\n';
  }

  /**
   * `parser.print_help()` then `sys.exit(0)`.
   *
   * @throws {SystemExit} always
   */
  exitWithHelp() {
    this.writeStdout(this.formatHelp());
    throw new SystemExit(EXIT_OK);
  }

  /**
   * `parser.error(message)`: usage line and error line to stderr, exit 2.
   *
   * @param {string} message
   * @throws {SystemExit} always
   */
  error(message) {
    this.writeStderr(`${this.formatUsage()}\n`);
    this.writeStderr(`${this.prog}: error: ${message}\n`);
    throw new SystemExit(EXIT_USAGE_ERROR);
  }

  /**
   * Whether a token should be read as an option rather than a value.
   *
   * Follows argparse's `_parse_optional`: a bare `-`, a token that looks like a
   * negative number (given no negative-number-like options are registered), and
   * anything containing a space are all values.
   *
   * @param {string} token
   * @returns {boolean}
   */
  looksLikeOption(token) {
    if (!token.startsWith('-')) return false;
    if (token === '-' || token === '--') return false;
    if (NEGATIVE_NUMBER.test(token)) return false;
    if (token.includes(' ')) return false;
