  /**
   * Resolve a written option string against the registered options, honouring
   * argparse's unique-prefix abbreviation (`--h` matches `--help`).
   *
   * @param {string} token
   * @returns {{optional: Optional}|{ambiguous: string[]}|null}
   */
  resolveOption(token) {
    for (const optional of this.optionals) {
      if (optional.optionStrings.includes(token)) return { optional };
    }
    if (!token.startsWith('--')) return null;

    /** @type {Optional[]} */
    const matches = [];
    /** @type {string[]} */
    const matched = [];
    for (const optional of this.optionals) {
      for (const option of optional.optionStrings) {
        if (option.startsWith('--') && option.startsWith(token)) {
          matches.push(optional);
          matched.push(option);
        }
      }
    }
    if (matches.length === 1) return { optional: matches[0] };
    if (matches.length > 1) return { ambiguous: matched };
    return null;
  }

  /**
   * Convert a raw string through an option's `type`, erroring the way argparse
   * does when the conversion is rejected.
   *
   * @param {Optional} optional
   * @param {string} raw
   * @returns {*}
   */
  convertValue(optional, raw) {
    if (!optional.type) return raw;
    const result = optional.type.convert(raw);
    if (!result.ok) {
