  parseArgs(argv) {
    /** @type {Record<string, *>} */
    const namespace = {};
    /** @type {Set<Optional>} */
    const seen = new Set();
    /** @type {string[]} */
    const extras = [];

    let onlyPositionalsRemain = false;
    let index = 0;
    while (index < argv.length) {
      const token = argv[index];
      index += 1;

      if (!onlyPositionalsRemain && token === '--') {
        // argparse consumes the first `--` and treats everything after it as
        // positional.
        onlyPositionalsRemain = true;
        continue;
      }

      if (onlyPositionalsRemain || !this.looksLikeOption(token)) {
        // No positionals are registered, so anything here is unrecognized.
        extras.push(token);
        continue;
      }

      // Split the `--opt=value` form.
      let written = token;
      let explicitValue = null;
      const equals = token.indexOf('=');
      if (token.startsWith('--') && equals !== -1) {
        written = token.slice(0, equals);
        explicitValue = token.slice(equals + 1);
      }

      const resolved = this.resolveOption(written);
      if (resolved === null) {
        extras.push(token);
        continue;
      }
      if ('ambiguous' in resolved) {
        this.error(
          `ambiguous option: ${written} could match ${resolved.ambiguous.join(', ')}`,
        );
      }

      const { optional } = resolved;
      if (optional.action === 'help') {
        this.exitWithHelp();
      }

      let raw = explicitValue;
      if (raw === null) {
        const next = index < argv.length ? argv[index] : null;
        // A token that looks like an option is never consumed as a value.
        if (next === null || this.looksLikeOption(next)) {
          this.error(`argument ${optional.displayName}: expected one argument`);
        }
        raw = next;
        index += 1;
      }

      // Last occurrence wins, matching argparse's plain `store` action.
      namespace[optional.dest] = this.convertValue(optional, raw);
      seen.add(optional);
    }

    const missing = this.optionals
      .filter((optional) => optional.required && !seen.has(optional))
      .map((optional) => optional.displayName);
    if (missing.length > 0) {
      this.error(`the following arguments are required: ${missing.join(', ')}`);
    }

    if (extras.length > 0) {
      this.error(`unrecognized arguments: ${extras.join(' ')}`);
    }

    return namespace;
  }
}

