const LINE_BUILD_CALL = 15; // `struct_format.build(...)` inside main()

/**
 * The body of the Python `main()`.
 *
 * @param {string[]} argv the argument tokens, without the program name
 * @param {{prog: string, stdout: (text: string) => void,
 *          stderr: (text: string) => void}} io
 */
function main(argv, io) {
  const parser = new ArgumentParser({
    prog: io.prog,
    stdout: io.stdout,
    stderr: io.stderr,
  });
  parser.addArgument('--a', { type: intType, required: true });
  parser.addArgument('--b', { type: intType, required: true });
