  // "field1" / construct.Int8ul  ->  construct.field('field1', construct.Int8ul)
  const structFormat = new construct.Struct(
    construct.field('field1', construct.Int8ul), // define first field
    construct.field('field2', construct.Int8ul), // define second field
  );
  const data = pythonStack.call(frame(PY_SOURCE, LINE_BUILD_CALL, 'main'), () =>
    structFormat.build({ field1: args.a, field2: args.b }),
  );
