}

/**
 * Module-level entry: run `main()` and translate the Python-level outcomes into
 * process exit codes.
 *
 *   0 -- success, or `--help`
 *   1 -- an unhandled construct exception (traceback on stderr, stdout empty)
 *   2 -- an argparse command-line error
 */
function runModule() {
  const io = {
    prog: deriveProgName(process.argv),
    stdout: (text) => process.stdout.write(text),
    stderr: (text) => process.stderr.write(text),
  };

  try {
    pythonStack.call(frame(PY_SOURCE, LINE_MODULE_CALL, '<module>'), () =>
      main(process.argv.slice(2), io),
