#!/usr/bin/env node
// Randomised differential fuzzer: generate odd argv vectors, run both binaries,
// compare normalised stdout/stderr/exit code.
import { spawnSync } from 'node:child_process';

const REF = '/workspace/dataset/test3_executable';
const PORT = '/tmp/cand_c1/test3.mjs';

const norm = (text) =>
  text
    .replace(/^usage: \S+/gm, 'usage: PROG')
    .replace(/^\S+: error:/gm, 'PROG: error:')
    .replace(/^\[PYI-\d+:ERROR\]/gm, '[PYI-PID:ERROR]');

const run = (cmd, args) => {
  const r = spawnSync(cmd, args, { encoding: 'utf8' });
  return { out: norm(r.stdout ?? ''), err: norm(r.stderr ?? ''), code: r.status };
};

const POOL = [
  '--a', '--b', '--c', '--help', '-h', '--h', '--he', '--', '-', '-5', '--a=1',
  '--b=255', '0', '1', '16', '255', '256', '-1', 'abc', '', '1_6', '_1', '1__2',
  '0x10', '1e5', '1.5', '  16  ', '\t42\n', '+16', '016', '39', '34', '92', '9',
  '10', '13', '127', '128', 'extra', '4 2', '- 5', "a'b", 'a"b', "a'b\"c", 'a\\b',
  ' 5', '１２', '٣', '\u{1d7df}', '99999999999999999999',
  '--a=abc', '--b=', '=1', '--=1', 'x\u{1f389}', '\x1c5', '--A', '--aa', '1,2',
];

const pick = (n) =>
  Array.from({ length: n }, () => POOL[Math.floor(Math.random() * POOL.length)]);

let pass = 0;
const failures = [];
const ROUNDS = Number(process.argv[2] ?? 600);

for (let i = 0; i < ROUNDS; i += 1) {
  const args = pick(1 + Math.floor(Math.random() * 5));
  const a = run(REF, args);
  const b = run('node', [PORT, ...args]);
  if (a.out === b.out && a.err === b.err && a.code === b.code) {
    pass += 1;
  } else {
    failures.push({ args, ref: a, port: b });
  }
}

console.log(`fuzz rounds=${ROUNDS} pass=${pass} fail=${failures.length}`);
for (const f of failures.slice(0, 8)) {
  console.log('\nARGS', JSON.stringify(f.args));
  console.log(' ref  code=%s out=%j err=%j', f.ref.code, f.ref.out, f.ref.err);
  console.log(' port code=%s out=%j err=%j', f.port.code, f.port.out, f.port.err);
}
process.exitCode = failures.length === 0 ? 0 : 1;
